# Range Range ### Быстрый старт Быстрый старт ```tsx
import React from 'react';
import { Range } from '@salutejs/sdds-finai';

export function App() {
    return (
        <div>
            <Range
                label="Диапазон значений"
                leftHelper="Введите два значения"
                firstPlaceholder="От"
                secondPlaceholder="До"
                dividerVariant="dash"
            />
        </div>
    );
}
```

```tsx
import React, { useState } from 'react';
import { Range } from '@salutejs/sdds-finai';

export function App() {
    const [firstValue, setFirstValue] = useState('');
    const [secondValue, setSecondValue] = useState('');

    return (
        <div>
            <Range
                firstValue={firstValue}
                secondValue={secondValue}
                label="Диапазон значений"
                leftHelper="Введите два значения"
                firstPlaceholder="От"
                secondPlaceholder="До"
                dividerVariant="dash"
                onChangeFirstValue={(e) => {
                    setFirstValue(e.target.value);
                }}
                onChangeSecondValue={(e) => {
                    setSecondValue(e.target.value);
                }}
            />
        </div>
    );
}
```

### Управление внешним видом Управление внешним видом Внешний вид компонента зависит от свойств  `appearance` ,  `size` .  `appearance="viewMode"`  — режим просмотра. ```tsx
import React from 'react';
import { Range } from '@salutejs/sdds-finai';

export function App() {
    return (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '2rem' }}>
            <Range
                appearance="default"
                label="Appearance default"
                firstPlaceholder="От"
                secondPlaceholder="До"
                dividerVariant="dash"
            />
            <Range
                appearance="viewMode"
                label="Appearance viewMode"
                firstValue="100"
                secondValue="500"
                readOnly
                dividerVariant="dash"
            />
        </div>
    );
}
```

Размер компонента зависит от свойства  `size` : ```tsx
import React from 'react';
